<?php
namespace App\Livewire\Contracts;
use App\Models\Employee; use App\Models\EmployeeContract; use App\Services\ContractService; use Carbon\Carbon; use Livewire\Component;
class Index extends Component { public ?int $employeeId=null; public string $type='indefinite'; public string $startDate=''; public string $endDate=''; public string $contractNumber=''; public function mount():void{$this->startDate=now()->toDateString();} public function create(ContractService $service):void{$this->authorize('manage-hr');$d=$this->validate(['employeeId'=>'required|exists:employees,id','type'=>'required|in:indefinite,fixed_term,temporary,part_time','startDate'=>'required|date','endDate'=>'nullable|date','contractNumber'=>'nullable|string|max:255']);$service->create(Employee::findOrFail($d['employeeId']),['type'=>$d['type'],'start_date'=>$d['startDate'],'end_date'=>$d['endDate']?:null,'contract_number'=>$d['contractNumber']?:null],auth()->id());$this->reset('employeeId','endDate','contractNumber');} public function activate(int $id,ContractService $service):void{$this->authorize('manage-hr');$service->activate(EmployeeContract::findOrFail($id));} public function render(ContractService $service){$service->expireDue(Carbon::today());return view('livewire.contracts.index',['employees'=>Employee::orderBy('name')->get(),'contracts'=>EmployeeContract::with('employee')->latest('start_date')->get(),'expiring'=>$service->expiringWithin(Carbon::today(),30)]);} }
